// Save each extracted icon to the output folder with appropriate .ico extension.

using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using Aspose.Html;
using Aspose.Html.Dom;
using Aspose.Html.Dom.Svg;
using Aspose.Html.Services;

class Program
{
    static void Main()
    {
        try
        {
            // Prepare sample HTML with icon links (data URIs)
            string htmlContent = @"
<!DOCTYPE html>
<html>
<head>
    <link rel='icon' href='data:image/x-icon;base64,. 
";
            // Create output directory
            string outputFolder = "output";
            Directory.CreateDirectory(outputFolder);

            // Load HTML document from string
            Aspose.Html.Configuration configuration = new Aspose.Html.Configuration();
            Aspose.Html.HTMLDocument document = new Aspose.Html.HTMLDocument(htmlContent, "about:blank", configuration);

            // Get all <link> elements
            Aspose.Html.Collections.HTMLCollection links = document.GetElementsByTagName("link");
            int iconIndex = 0;

            foreach (Aspose.Html.Dom.Element element in links)
            {
                // Cast to HTMLLinkElement to access attributes
                Aspose.Html.HTMLLinkElement link = element as Aspose.Html.HTMLLinkElement;
                if (link == null)
                    continue;

                string rel = link.Rel?.ToLowerInvariant() ?? string.Empty;
                if (!rel.Contains("icon"))
                    continue;

                string href = link.Href;
                if (string.IsNullOrEmpty(href))
                    continue;

                // Handle data URI
                if (href.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
                {
                    // Example: data:image/x-icon;base64,AAAA...
                    int base64Index = href.IndexOf("base64,", StringComparison.OrdinalIgnoreCase);
                    if (base64Index < 0)
                        continue;

                    string base64Data = href.Substring(base64Index + 7);
                    byte[] iconBytes = Convert.FromBase64String(base64Data);
                    string outputPath = Path.Combine(outputFolder, $"icon_{iconIndex}.ico");
                    File.WriteAllBytes(outputPath, iconBytes);
                    Console.WriteLine($"Saved icon to: {outputPath}");
                    iconIndex++;
                }
                else
                {
                    // For external URLs, you would normally download the file.
                    // This example focuses on data URI icons only.
                    Console.WriteLine($"Skipping non-data URI href: {href}");
                }
            }

            Console.WriteLine("Icon extraction completed.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}